mapper.select:
SELECT DISTINCT
biv.* FROM  bbx_invitation_visitor biv
LEFT JOIN bbx_invitation bi ON biv.invite_id = bi.id


        AND biv.tenant_id =#{condition.tenantId}


        AND bi.invite_uid =#{condition.userId}


        AND biv.name like concat('%',#{condition.name},'%')


        AND biv.company like concat('%',#{condition.company},'%')


        AND biv.phone =#{condition.phone}


ORDER BY biv.create_time desc
